BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS core;
CREATE TABLE IF NOT EXISTS core.camm_catalogo (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), codigo text NOT NULL UNIQUE, nome text NOT NULL, posicao smallint NOT NULL DEFAULT 0, ativo boolean NOT NULL DEFAULT true, criado_em timestamptz NOT NULL DEFAULT now(), atualizado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS core.lista_catalogo (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lista text NOT NULL, codigo text NOT NULL, nome text NOT NULL, posicao smallint NOT NULL DEFAULT 0, ativo boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, criado_em timestamptz NOT NULL DEFAULT now(), atualizado_em timestamptz NOT NULL DEFAULT now(), UNIQUE(lista,codigo));
CREATE INDEX IF NOT EXISTS ix_lista_catalogo_lista ON core.lista_catalogo(lista,ativo,posicao,nome);
CREATE TABLE IF NOT EXISTS almox.familia (id text PRIMARY KEY, nome text NOT NULL, posicao smallint NOT NULL DEFAULT 0, ativo boolean NOT NULL DEFAULT true, criado_em timestamptz NOT NULL DEFAULT now(), atualizado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS almox.familia_campo (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), familia_id text NOT NULL REFERENCES almox.familia(id) ON DELETE CASCADE, chave text NOT NULL, rotulo text NOT NULL, obrigatorio boolean NOT NULL DEFAULT false, posicao smallint NOT NULL DEFAULT 0, ativo boolean NOT NULL DEFAULT true, UNIQUE(familia_id,chave));
CREATE INDEX IF NOT EXISTS ix_familia_campo_familia ON almox.familia_campo(familia_id,posicao);
ALTER TABLE almox.scm ALTER COLUMN camm DROP DEFAULT;
ALTER TABLE almox.scm ALTER COLUMN camm TYPE text USING camm::text;
ALTER TABLE almox.scm ALTER COLUMN camm SET DEFAULT 'CAMM 1';
ALTER TABLE almox.scm ALTER COLUMN urgencia DROP DEFAULT;
ALTER TABLE almox.scm ALTER COLUMN urgencia TYPE text USING urgencia::text;
ALTER TABLE almox.scm ALTER COLUMN urgencia SET DEFAULT 'media';
COMMIT;
